from typing import List

def calculate_minimum_tour_length(n: int, m: int, x: List[int]) -> int:
    cost = [0] * n

    for i in range(m - 1):
        l, r = min(x[i], x[i + 1]), max(x[i], x[i + 1])
        cost[l] += 1
        if r < n:
            cost[r] -= 1

    ans = float('inf')
    current_cost = 0
    for i in range(n):
        current_cost += cost[i]
        if current_cost < ans:
            ans = current_cost

    return ans
